27:/** An ATS host family and the posting id inside its URL. */
28:export interface PostingIdentity {
29:  /** Which board host family — ids are only comparable within one. */
30:  family: string;
31:  /** The posting id as the URL spells it. */
32:  id: string;
33:  /**
34:   * The company's board slug, when the URL carries one — what the ATS APIs key
35:   * on (`/v1/boards/<board>/jobs/<id>`).
36:   *
37:   * Null on an embedded form, where `gh_jid` names the posting but nothing
38:   * names the board. A null board means the liveness probe cannot ask, and
39:   * "cannot ask" is `unknown`, never `dead`.
40:   */
41:  board: string | null;
42:}
43:
44:/**
45: * The board slug is the first path segment, minus the ones that are API
46: * scaffolding rather than a company.
47: *
48: * Deliberately duplicated from `parseAtsBoard` (@fbj/adapters `ats/board.ts`),
49: * which answers the same question for a different purpose — registering a whole
50: * board as a discovery source. `core` sits below `adapters`, so importing it
51: * would invert the layering for fifteen lines; this file already duplicates the
52: * host regexes for the same reason.
53: */
54:function firstSegment(
55:  path: string,
56:  skip: readonly string[] = [],
57:): string | null {
58:  for (const part of path.split("/")) {
59:    if (!part) continue;
60:    if (skip.includes(part.toLowerCase())) continue;
61:    return part;
62:  }
63:  return null;
64:}
